public str getName()
{
    return fieldPName(MCRInventTable, ContEventDuration);
}

public Set getAllowedValues()
{   
    MCRInventTable  mcrInventTable;
    var             ret = new Set(Types::Integer);

    while select ContEventDuration from mcrInventTable
        group by ContEventDuration
    {   
        if (!ret.in(mcrInventTable.ContEventDuration))
        {
            ret.add(mcrInventTable.ContEventDuration);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(MCRInventTable, ContEventDuration));
    qbr.value(queryValue(_value));
}
